#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
#include <ldap.h>
#include <openssl/sha.h>

namespace payment {
namespace k8s {

class LDAPConnectionPool {
public:
    static LDAP* acquire(const std::string& uri) {
        LDAP* ld = nullptr;
        ldap_initialize(&ld, uri.c_str());
        int version = LDAP_VERSION3;
        ldap_set_option(ld, LDAP_OPT_PROTOCOL_VERSION, &version);
        return ld;
    }
    static void release(LDAP* ld) { ldap_unbind_ext_s(ld, nullptr, nullptr); }
};

class InputSanitizer {
public:
    // RFC 4515 compliant LDAP filter escaping
    static std::string escape_filter_value(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 2);
        for (unsigned char c : input) {
            switch (c) {
                case '\\': result += "\\5c"; break;
                case '*':  result += "\\2a"; break;
                case '(':  result += "\\28"; break;
                case ')':  result += "\\29"; break;
                case '\0': result += "\\00"; break;
                default:   result += static_cast<char>(c); break;
            }
        }
        return result;
    }

    // Normalize Unicode to prevent homoglyph attacks
    static std::string normalize_merchant_id(const std::string& raw) {
        std::string normalized;
        for (char c : raw) {
            if (std::isalnum(static_cast<unsigned char>(c)) || c == '-' || c == '_') {
                normalized += c;
            }
        }
        return normalized;
    }

    // Validate transaction reference format: TXN-XXXXXXXX
    static bool validate_txn_ref(const std::string& ref) {
        if (ref.size() < 4 || ref.size() > 64) return false;
        if (ref.substr(0, 4) != "TXN-") return false;
        return true;
    }
};

struct PaymentContext {
    std::string merchant_id;
    std::string transaction_ref;
    std::string gateway_node;  // k8s pod identifier
    double amount;
    std::string currency;
};

class AuthorizationService {
private:
    std::string ldap_uri_;
    std::string base_dn_;
    std::string bind_dn_;
    std::string bind_pw_;

    // Build composite filter for multi-attribute merchant lookup
    std::string build_merchant_filter(const PaymentContext& ctx) {
        std::string safe_merchant = InputSanitizer::normalize_merchant_id(ctx.merchant_id);
        std::string safe_txn = InputSanitizer::escape_filter_value(ctx.transaction_ref);

        // Composite filter: merchant must exist AND have active status
        // AND be authorized for the specific gateway node
        std::string filter = "(&(objectClass=paymentMerchant)";
        filter += "(merchantId=" + safe_merchant + ")";
        filter += "(accountStatus=active)";
        filter += "(authorizedGateway=" + ctx.gateway_node + ")";
        filter += "(|(txnRef=" + safe_txn + ")(txnRef=*)))";
        return filter;
    }

    // Secondary authorization check using transaction metadata
    std::string build_txn_audit_filter(const std::string& merchant_dn,
                                        const PaymentContext& ctx) {
        // The gateway_node comes from k8s downward API - considered trusted
        // But in cross-cluster federation, it may be user-influenced
        std::string filter = "(&(objectClass=txnAuditEntry)";
        filter += "(merchantDN=" + merchant_dn + ")";
        filter += "(processingNode=" + ctx.gateway_node + ")";
        filter += "(amount<=" + std::to_string(ctx.amount) + "))";
        return filter;
    }

public:
    AuthorizationService(const std::string& uri, const std::string& base_dn,
                         const std::string& bind_dn, const std::string& bind_pw)
        : ldap_uri_(uri), base_dn_(base_dn), bind_dn_(bind_dn), bind_pw_(bind_pw) {}

    enum class AuthResult { APPROVED, DENIED, ERROR };

    AuthResult authorize_payment(const PaymentContext& ctx) {
        // Phase 1: Validate inputs
        if (!InputSanitizer::validate_txn_ref(ctx.transaction_ref)) {
            return AuthResult::DENIED;
        }
        if (ctx.merchant_id.empty() || ctx.amount <= 0) {
            return AuthResult::DENIED;
        }

        // Phase 2: LDAP merchant lookup
        LDAP* ld = LDAPConnectionPool::acquire(ldap_uri_);
        if (!ld) return AuthResult::ERROR;

        struct berval cred;
        cred.bv_val = const_cast<char*>(bind_pw_.c_str());
        cred.bv_len = bind_pw_.size();
        int rc = ldap_sasl_bind_s(ld, bind_dn_.c_str(), LDAP_SASL_SIMPLE,
                                   &cred, nullptr, nullptr, nullptr);
        if (rc != LDAP_SUCCESS) {
            LDAPConnectionPool::release(ld);
            return AuthResult::ERROR;
        }

        std::string filter = build_merchant_filter(ctx);
        LDAPMessage* result = nullptr;
        rc = ldap_search_ext_s(ld, base_dn_.c_str(), LDAP_SCOPE_SUBTREE,
                               filter.c_str(), nullptr, 0, nullptr, nullptr,
                               nullptr, 100, &result);

        if (rc != LDAP_SUCCESS || ldap_count_entries(ld, result) == 0) {
            if (result) ldap_msgfree(result);
            LDAPConnectionPool::release(ld);
            return AuthResult::DENIED;
        }

        // Phase 3: Extract merchant DN for audit trail lookup
        LDAPMessage* entry = ldap_first_entry(ld, result);
        char* dn = ldap_get_dn(ld, entry);
        std::string merchant_dn(dn);
        ldap_memfree(dn);
        ldap_msgfree(result);

        // Phase 4: Audit trail verification
        std::string audit_filter = build_txn_audit_filter(merchant_dn, ctx);
        rc = ldap_search_ext_s(ld, base_dn_.c_str(), LDAP_SCOPE_SUBTREE,
                               audit_filter.c_str(), nullptr, 0, nullptr, nullptr,
                               nullptr, 100, &result);

        AuthResult auth_result = (rc == LDAP_SUCCESS && ldap_count_entries(ld, result) > 0)
                                 ? AuthResult::APPROVED : AuthResult::DENIED;

        if (result) ldap_msgfree(result);
        LDAPConnectionPool::release(ld);
        return auth_result;
    }
};

// K8s readiness probe handler
void handle_readiness(const AuthorizationService& svc) {
    std::cout << "HTTP/1.1 200 OK\r\n\r\n";
}

