} // namespace payment

int main() {
    // Configuration from k8s ConfigMap/Secret
    std::string ldap_uri = std::getenv("LDAP_URI") ? std::getenv("LDAP_URI") : "ldap://ldap-svc.payment.svc.cluster.local";
    std::string base_dn = std::getenv("LDAP_BASE_DN") ? std::getenv("LDAP_BASE_DN") : "dc=payment,dc=internal";
    std::string bind_dn = std::getenv("LDAP_BIND_DN") ? std::getenv("LDAP_BIND_DN") : "cn=payment-svc,dc=payment,dc=internal";
    std::string bind_pw = std::getenv("LDAP_BIND_PW") ? std::getenv("LDAP_BIND_PW") : "";

    payment::k8s::AuthorizationService auth_svc(ldap_uri, base_dn, bind_dn, bind_pw);

    // Simulated incoming payment from gateway
    payment::k8s::PaymentContext ctx;
    ctx.merchant_id = "merchant-001";
    ctx.transaction_ref = "TXN-A1B2C3D4";
    ctx.gateway_node = std::getenv("HOSTNAME") ? std::getenv("HOSTNAME") : "gateway-pod-0";
    ctx.amount = 150.00;
    ctx.currency = "USD";

    auto result = auth_svc.authorize_payment(ctx);
    std::cout << "Authorization: " << static_cast<int>(result) << std::endl;
    return 0;
}
